WITH products_by_supplier AS (SELECT supplier_id, COUNT(CASE WHEN brand = 'Acme' THEN 1 END) AS acme_count, ROUND(STDDEV(stock_qty), 2) AS stddev_stock_qty FROM products WHERE LENGTH(product_name) < 13 GROUP BY supplier_id) SELECT s.id, s.rating, pbs.acme_count, pbs.stddev_stock_qty FROM suppliers s LEFT JOIN products_by_supplier pbs ON s.id = pbs.supplier_id WHERE pbs.stddev_stock_qty >= 66;
